import{_ as a,c as r,o as t,ag as o}from"./chunks/framework.ARG558ZT.js";const m=JSON.parse('{"title":"P-335: resumable approved tool workflow","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/resumable-workflow.md","filePath":"practice/applied-ai/resumable-workflow.md"}'),n={name:"practice/applied-ai/resumable-workflow.md"};function s(i,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="p-335-resumable-approved-tool-workflow" tabindex="-1">P-335: resumable approved tool workflow <a class="header-anchor" href="#p-335-resumable-approved-tool-workflow" aria-label="Permalink to “P-335: resumable approved tool workflow”">​</a></h1><p><strong>Learner status: still required.</strong> Refines <a href="./../ai-project.html#p-335">existing P-335</a>, using the same notes and evaluation cases. Prerequisites: typed tool dispatch, current identity/source checks, SQLite transactions/CAS, cancellation/budgets and <a href="./../../applied-ai/workflows/resumable-runs.html">resumable-run design</a>. Use <a href="./#evidence-for-every-stage">shared evidence</a>.</p><h2 id="wf-1-fixed-read-propose-validate" tabindex="-1">WF-1: fixed read, propose, validate <a class="header-anchor" href="#wf-1-fixed-read-propose-validate" aria-label="Permalink to “WF-1: fixed read, propose, validate”">​</a></h2><p><strong>Scope:</strong> one task-scoped note lookup and a proposed exact title change. Start with deterministic application-owned proposals; one bounded model-directed lookup/finish branch is optional, separately evaluated.</p><p><strong>Acceptance:</strong> complete arguments/results validate; exact names and current principal/task scope are outside model control. Unknown tool, extra tenant field, forged call ID, partial arguments and exhausted rounds cause zero disallowed I/O. Map validated outcomes to fixed trace categories; do not log raw arguments/results. Terminal states schedule no more work. A model&#39;s <code>approved</code> or <code>checked</code> field has no authority.</p><p><strong>Failures/evidence:</strong> three temporary read failures end under a two-retry policy; denied/schema failures execute once; repeated lookup cannot loop forever. Retain call/result identity, stage trace, allow/deny counts and schema/routing counterexamples. Model behavior is unmeasured if only a fake proposal was used.</p><h2 id="wf-2-artifacts-and-durable-approval" tabindex="-1">WF-2: artifacts and durable approval <a class="header-anchor" href="#wf-2-artifacts-and-durable-approval" aria-label="Permalink to “WF-2: artifacts and durable approval”">​</a></h2><p><strong>Scope:</strong> one owned local database and bounded immutable input/proposal/result artifacts. Add authenticated approval through a separate trusted test route/UI; fixture-seeded rows test the executor but do not prove a real person approved.</p><p><strong>Acceptance:</strong> checkpoint schema includes owner/job/revision, exact artifact references/digests, source/configuration revisions, remaining limits and expiry. Persist artifact plus stage atomically or use documented staging/commit/cleanup. Show the exact command/resource/version to the actor; bind persisted approval to digest/principal/scope/expiry. Editing the proposal needs a new approval. The model allowlist cannot call the approval route.</p><p><strong>Failures:</strong> absent/tampered artifact, stale CAS, wrong owner/configuration, expired/revoked approval, changed resource version and malicious source instructions. Reopen the file in a new process and resume only valid/current artifacts. No RAM-only graph snapshot is counted as durable.</p><p><strong>Evidence:</strong> actual restart/serialization records, denial results, UI/route observations, current source decisions and proof that a changed command cannot reuse approval.</p><h2 id="wf-3-receipt-and-interrupted-recovery" tabindex="-1">WF-3: receipt and interrupted recovery <a class="header-anchor" href="#wf-3-receipt-and-interrupted-recovery" aria-label="Permalink to “WF-3: receipt and interrupted recovery”">​</a></h2><p><strong>Scope:</strong> one local versioned rename, stable operation ID and atomic effect/receipt. No email/payment/external write is necessary.</p><p><strong>Acceptance:</strong> inject interruption before dispatch, after commit/before reply and after receipt/before job advance. Reopen/resume; same operation/same command yields the original receipt with one version increment, changed command conflicts. Competing workers cannot dispatch merely from the same stale counter; use a single owner initially and a tested atomic claim if concurrency is added.</p><p><strong>Failures:</strong> approval revoked on resume, lock/store outage, transaction failure between effect and receipt, missing result artifact and stale worker update. For a fake external adapter, simulate committed-but-reply-lost: persist unknown, query its authoritative status and never mint a new key blindly. Local SQL does not roll back remote effects.</p><p><strong>Evidence:</strong> command hash/operation ID/checkpoint revision, effect count, receipts and rollback/reconciliation observations. A lease expiring is not proof the remote job stopped.</p><h2 id="wf-4-time-retries-budgets-and-evaluation" tabindex="-1">WF-4: time, retries, budgets and evaluation <a class="header-anchor" href="#wf-4-time-retries-budgets-and-evaluation" aria-label="Permalink to “WF-4: time, retries, budgets and evaluation”">​</a></h2><p><strong>Scope:</strong> at most five tools/one write per run, a declared UTC expiry plus local monotonic durations, per-operation deadlines and a conservative local spend reserve. Values are exercise caps, not industry defaults.</p><p><strong>Acceptance:</strong> charge reservation before calls and preserve it across restart; total calls/bytes/time/spend cannot reset on resume. Classified retries honor backoff/server minima or defer. Cancellation reaches owned work and does not retry. Unknown usage remains held; settlement replay cannot refund twice. A pending reservation causes reconciliation, not a second job.</p><p><strong>Failures/evidence:</strong> blocked adapter, timeout, cancellation during sleep/read, over-budget proposal, missing usage, underestimate overrun and duplicate concurrent reservation. Compare complete task success and safety against the fixed baseline; record all attempts/failures, safe correlated traces, hard gates and rubric judgments. Real provider quality, distributed leases, real human consent and external-effect integration remain unperformed unless separately observed.</p>',20)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
